package com.coolxer.model.dih.dataapp;

import com.fasterxml.jackson.databind.PropertyNamingStrategies;
import com.fasterxml.jackson.databind.annotation.JsonNaming;
import lombok.Data;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Server-compiled data application specification. The model may only supply
 * this structure; AMIS nodes, URLs and scripts are generated by the backend.
 */
@Data
@JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
public class DataAppSpec {

    public static final String SCHEMA_VERSION = "1.0";

    private String schemaVersion = SCHEMA_VERSION;
    private String appId;
    private String name;
    private String description;
    private String homePageId;
    private List<DataAppPage> pages = new ArrayList<>();
    private DataAppMenu menu;

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DataAppPage {
        private String pageId;
        private String title;
        private String icon;
        private List<DataAppBlock> blocks = new ArrayList<>();
    }

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DataAppBlock {
        private String blockId;
        private String type;
        private String title;
        private String description;
        private Integer width;
        private DataAppQuery query;
        private List<DataAppMetricCard> metricCards = new ArrayList<>();
        private DataAppRecords records;
    }

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DataAppQuery {
        private String tool;
        private String entity;
        private Map<String, Object> request = new LinkedHashMap<>();
    }

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DataAppMetricCard {
        private String label;
        private String field;
        private String prefix;
        private String suffix;
        private Integer precision;
    }

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DataAppRecords {
        private String entity;
        private List<DataAppRecordColumn> columns = new ArrayList<>();
        private List<DataAppRecordFilter> filters = new ArrayList<>();
        private Boolean detail = true;
        private Boolean create = false;
        private Boolean update = false;
        private Boolean delete = false;
        private String defaultSortField;
        private String defaultSortDirection = "desc";
        private Integer pageSize = 20;
    }

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DataAppRecordColumn {
        private String field;
        private String label;
        private Boolean searchable = false;
        private Boolean sortable = true;
        private Integer width;
    }

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DataAppRecordFilter {
        private String field;
        private String label;
        private String operator = "equal";
        private String inputType;
    }

    @Data
    @JsonNaming(PropertyNamingStrategies.SnakeCaseStrategy.class)
    public static class DataAppMenu {
        private String name;
        private Integer parentId;
        private Integer orderNumber;
    }
}
